-- ################################################################################################
-- # 317 - Georgia Medicaid NEMT driver requirements, as drafts.
-- #
-- # From the Georgia Department of Community Health, Part II Policies and Procedures for
-- # Non-Emergency Transportation Broker Services, April 1, 2016 (Seed Data/GA). Sections 300.12
-- # (driver qualifications), 300.13 (driver training) and 400.6(5) (driver records).
-- #
-- # Each reaches a company in or operating in Georgia that carries Medicaid trips, and nobody else.
-- # Each reads the evidence the matching rule already reads, so it is one more source on an existing
-- # qualification - a Georgia company's driver has one license row, with the DCH section beside it.
-- #
-- # All are drafts. The manual is dated 2016 and may have been superseded; nothing here is enforced
-- # until a reviewer approves it against the current manual.
-- #
-- # Not here, on purpose: duties that fall on the broker rather than the transportation company
-- # (monthly OIG and SAM checks of owners, the Death Master File check of drivers), and 300.12(5)'s
-- # removal after two at-fault violations or accidents under the contract, which needs a count of
-- # contract accidents per driver that the file does not keep yet.
-- ################################################################################################

UPDATE qualificationcatalog SET name = 'Minimum driver age' WHERE code = 'DRV-009';
INSERT IGNORE INTO qualificationcatalog (code, name, area, sortorder) VALUES
  ('TRN-014', 'Safety and sensitivity training', 'training', 57),
  ('TRN-015', 'Spill kit and biohazard removal training', 'training', 58);

INSERT IGNORE INTO credentialtypes (recordid, accountid, code, name, subject, maxagedays, requirestesting,
                                    defaultvaliddays, hasamount, category, description, added, active)
VALUES
  (UUID(), NULL, 'SAFETY_SENSITIVITY', 'Safety and sensitivity training', 'driver', NULL, 0, NULL, 0,
   'training', 'A certificate of completion, or the company''s own record of the training given. Record who provided it.',
   UTC_TIMESTAMP(), 1),
  (UUID(), NULL, 'SPILL_KIT_BIOHAZARD', 'Spill kit and biohazard removal training', 'driver', NULL, 0, NULL, 0,
   'training', 'A certificate of completion, or the company''s own record of the training given. Record who provided it.',
   UTC_TIMESTAMP(), 1);

